# Writes the hedra command files of the mountain shrine's world and effects: terrace.txt (paved
# terrace, steps, moss, cliff), torii.txt (the gate the bells hang from, with the bell cords),
# lantern.txt, pine.txt, peaks.txt (far mountains with snow), moon.txt, clouds.txt, stars.txt,
# ripple.txt (the ring wave a bell sends out), note.txt (a rising spark).
# Run from models/env: /usr/bin/python3 make_env.py
# Up Z, front -Y (hedra); colours exact Citrink. World (glTF) = (x, z, -y) of hedra.
import math, random

HEX = {"white": "ffffff", "yellow": "fcf660", "lime": "b2d942", "green": "52c33f",
       "teal": "166e7a", "steel": "254d70", "navy": "252446", "ink": "201533"}
def col(n):
    h = HEX[n]; r, g, b = (int(h[i:i + 2], 16) / 255 for i in (0, 2, 4))
    return f"--base-color {r:.4f} {g:.4f} {b:.4f}"

# the bells: x (world) and bake scale; the game reads the same numbers (game.as BELL_X, BELL_S)
BELL_X = [-3.6, -1.2, 1.2, 3.5]
BELL_S = [1.35, 1.2, 1.08, 0.96]
BELL_H = 1.9         # the hero bell's height (lip to loop top) at scale 1
NUKI_Y = 4.75        # underside of the lower beam (tie beam) the cords hang from
HANG_Y = 4.45        # the bells' hang point (top of the loop), world y
GATE_Z = -1.0        # the gate's plane (world z), hedra y = +1.0

files = {}

# ---------------------------------------------------------------- terrace
rnd = random.Random(3)
moss = []
for i in range(16):
    x = rnd.choice([-1, 1]) * rnd.uniform(4.5, 8.0); y = rnd.uniform(-3.0, 3.0)
    moss.append(f"((pos.x - ({x:.2f}))*(pos.x - ({x:.2f})) + (pos.y - ({y:.2f}))*(pos.y - ({y:.2f})) < {rnd.uniform(0.3, 0.7)**2:.3f})")
steps = []
for i in range(4):
    top = -0.3 * (i + 1); y0 = -3.5 - 0.55 * i; y1 = y0 - 0.55
    w = 2.4 + 0.3 * i
    steps.append(f"add mesh cube --name Step{i} --size 1 --location 0 {(y0 + y1) / 2:.3f} {(top - 1.6) / 2:.3f}")
    steps.append(f"scale {2 * w:.2f} 0.55 {top + 1.6:.3f}\napply --scale")
step_names = " ".join(f"Step{i}" for i in range(4))
files["terrace"] = f"""# Terrace: a paved stone terrace 17 x 7 m (top at z 0) on a mountain top, moss at its edges, four
# steps down the front, a rough cliff cone under it that sinks into the clouds. Generated by
# make_env.py. Up Z, front -Y.
new
material new Paving {col('steel')} --no-slot
material new Moss {col('green')} --no-slot
material new Rock {col('navy')} --no-slot
material new Path {col('teal')} --no-slot
add mesh cube --name Top --size 1 --location 0 0 -0.5
scale 17 7 1
apply --scale
material assign Rock
mode edit
select face where "normal.z < -0.9"
delete only-faces
select face where "normal.z > 0.9"
subdivide --cuts 16
select face where "normal.z > 0.9"
material assign Paving
select face where "normal.z > 0.9 && pos.x > -1.6 && pos.x < 1.6"
material assign Path
select face where "normal.z > 0.9 && ({' || '.join(moss)})"
material assign Moss
mode object
""" + "\n".join(steps) + f"""
select {step_names}
material assign Paving
add mesh cone --name Cliff --vertices 12 --radius1 9.6 --radius2 4.0 --depth 5.5 --location 0 0 -3.75 --rotation 180 0 0
apply --rotation
scale 1 0.55 1
apply --scale
material assign Rock
mode edit
select face where "normal.z > 0.9 || normal.z < -0.9"
delete only-faces
select vert where "pos.z < -1.2"
randomize --amount 0.5 --seed 4
mode object
select Top Cliff {step_names}
active Top
join
shade flat
export terrace.glb
"""

# ---------------------------------------------------------------- torii (the bell gate)
cords = []
for i, (x, s) in enumerate(zip(BELL_X, BELL_S)):
    top = NUKI_Y; bot = HANG_Y - 0.06
    cords.append(f"add mesh cube --name Cord{i} --size 1 --location {x:.2f} 1.0 {(top + bot) / 2:.3f}")
    cords.append(f"scale 0.12 0.12 {top - bot + 0.1:.3f}\napply --scale")
cord_names = " ".join(f"Cord{i}" for i in range(4))
files["torii"] = f"""# Torii: two lacquered posts, a tie beam (nuki) the bell cords hang from, a dark top beam (kasagi)
# (steel grey) with upturned ends, a name plaque between the beams, the posts' black feet and the four cords.
# Built in place: the gate stands at world z -1 (hedra y 1). Generated by make_env.py. Up Z, front -Y.
new
material new Lacquer {col('teal')} --no-slot
material new Cap {col('steel')} --no-slot
material new Cord {col('lime')} --no-slot
add mesh cylinder --name PostL --vertices 8 --radius 0.36 --depth 6.0 --location -5.4 1.0 3.0
add mesh cylinder --name PostR --vertices 8 --radius 0.36 --depth 6.0 --location 5.4 1.0 3.0
add mesh cube --name Nuki --size 1 --location 0 1.0 5.05
scale 12.6 0.42 0.6
apply --scale
add mesh cube --name Plaque --size 1 --location 0 0.95 5.65
scale 1.1 0.3 0.8
apply --scale
select PostL PostR Nuki Plaque
active PostL
join
rename PostL Frame
material assign Lacquer
add mesh cube --name KasaM --size 1 --location 0 1.0 6.25
scale 11.2 0.8 0.55
apply --scale
add mesh cube --name KasaL --size 1 --location -6.4 1.0 6.38
scale 2.4 0.8 0.55
apply --scale
set rotation 0 -9 0
apply --rotation
add mesh cube --name KasaR --size 1 --location 6.4 1.0 6.38
scale 2.4 0.8 0.55
apply --scale
set rotation 0 9 0
apply --rotation
add mesh cube --name FootL --size 1 --location -5.4 1.0 0.3
scale 0.95 0.95 0.6
apply --scale
add mesh cube --name FootR --size 1 --location 5.4 1.0 0.3
scale 0.95 0.95 0.6
apply --scale
select KasaM KasaL KasaR FootL FootR
active KasaM
join
rename KasaM Kasagi
material assign Cap
""" + "\n".join(cords) + f"""
select {cord_names}
active Cord0
join
rename Cord0 Cords
material assign Cord
select all
shade flat
export torii.glb
"""

# ---------------------------------------------------------------- stone lantern (toro)
files["lantern"] = f"""# Stone lantern (toro): a plinth, a post, a fire box with glowing windows, a wide pyramid roof and
# a knob. 1.2 x 1.2 x 2.5 m, origin on the ground. Generated by make_env.py. Up Z, front -Y.
new
material new Stone {col('steel')} --no-slot
material new Fire {col('yellow')} --no-slot
add mesh cylinder --name Plinth --vertices 6 --radius 0.6 --depth 0.3 --location 0 0 0.15
add mesh cylinder --name Post --vertices 6 --radius 0.22 --depth 0.9 --location 0 0 0.75
add mesh cylinder --name Shelf --vertices 6 --radius 0.55 --depth 0.18 --location 0 0 1.27
add mesh cone --name Roof --vertices 6 --radius1 0.85 --radius2 0.18 --depth 0.5 --location 0 0 2.06
add mesh ico-sphere --name Knob --subdivisions 1 --radius 0.17 --location 0 0 2.38
select Plinth Post Shelf Roof Knob
active Plinth
join
rename Plinth Lantern
material assign Stone
add mesh cube --name Box --size 1 --location 0 0 1.58
scale 0.66 0.66 0.46
apply --scale
material assign Fire
add mesh cube --name Pillars --size 1 --location 0 0 1.58
scale 0.78 0.3 0.46
apply --scale
material assign Stone
add mesh cube --name Pillars2 --size 1 --location 0 0 1.58
scale 0.3 0.78 0.46
apply --scale
material assign Stone
select all
shade flat
export lantern.glb
"""

# ---------------------------------------------------------------- pine (a wind-shaped mountain pine)
pads = [(0.0, 0.0, 3.0, 1.15), (0.9, 0.2, 2.35, 0.95), (-0.7, -0.1, 2.0, 0.85), (1.6, 0.0, 1.6, 0.75), (0.3, 0.1, 3.6, 0.7)]
pad_cmds = []
for i, (x, y, z, r) in enumerate(pads):
    pad_cmds.append(f"add mesh ico-sphere --name Pad{i} --subdivisions 1 --radius {r} --location {x} {y} {z}")
    pad_cmds.append(f"scale 1.3 1.0 0.45\napply --scale")
files["pine"] = f"""# Mountain pine: a leaning trunk with flat cloud-like needle pads (flattened icospheres).
# About 3.6 x 2 x 4 m, origin at the trunk's foot. Generated by make_env.py. Up Z, front -Y.
new
material new Bark {col('navy')} --no-slot
material new Needles {col('teal')} --no-slot
add mesh cylinder --name Trunk --vertices 6 --radius 0.22 --depth 3.2 --location 0.3 0 1.5 --rotation 0 12 0
apply --rotation
add mesh cylinder --name Branch --vertices 5 --radius 0.13 --depth 1.6 --location 1.1 0 1.8 --rotation 0 62 0
apply --rotation
select Trunk Branch
active Trunk
join
material assign Bark
""" + "\n".join(pad_cmds) + f"""
select {' '.join(f'Pad{i}' for i in range(len(pads)))}
active Pad0
join
rename Pad0 Needles
material assign Needles
mode edit
select all
randomize --amount 0.08 --seed 6
mode object
select all
shade flat
export pine.glb
"""

# ---------------------------------------------------------------- far peaks
# The camera is orthographic: far things keep their size, and a pitched view lifts them by
# z sin(pitch). So the "far" peaks are small and only 9 to 15 m behind, poking out of the sea of
# clouds behind the shrine, their bases sunk in it (and only the faces the camera sees).
peaks = [(-9.0, 10.5, 3.4, 2.6), (-6.2, 13.0, 4.4, 3.2), (6.8, 12.0, 4.0, 3.0), (9.5, 10.0, 3.0, 2.4), (-12.5, 9.0, 2.6, 2.0), (12.5, 9.5, 2.6, 2.2), (0.5, 15.0, 2.3, 3.6)]
pk = []
for i, (x, y, h, r) in enumerate(peaks):
    pk.append(f"add mesh cone --name Pk{i} --vertices 7 --radius1 {r} --radius2 0 --depth {h + 3} --location {x} {y} {(h + 3) / 2 - 3:.2f}")
    pk.append(f"mode edit\nselect face where \"normal.z > -0.5\"\nsubdivide --cuts 2\nselect vert where \"pos.z < {(h + 3) / 2 - 0.4:.2f}\"\nrandomize --amount {0.1 * r:.2f} --seed {i + 1}\nmode object")
files["peaks"] = f"""# Far peaks: seven small seven-sided cones, jagged, their tops white with snow, rising out of the
# clouds behind the shrine (hedra y 9..15 = world z -9..-15). Faces turned away from the camera and
# the buried bases are deleted. Generated by make_env.py.
new
material new Rock {col('navy')} --no-slot
material new Snow {col('white')} --no-slot
""" + "\n".join(pk) + f"""
select {' '.join(f'Pk{i}' for i in range(len(peaks)))}
active Pk0
join
rename Pk0 Peaks
material assign Rock
apply --location
mode edit
select face where "normal.z < -0.9 || normal.y > 0.35"
delete only-faces
select face where "pos.z < -1.2"
delete only-faces
select face where "pos.z > 2.1 && normal.z > 0.2"
material assign Snow
mode object
shade flat
export peaks.glb
"""

# ---------------------------------------------------------------- moon
files["moon"] = f"""# Moon: a big faceted disc (a flat 16-sided cylinder) facing the camera, unlit in the scene.
new
material new Moon {col('white')} --no-slot
material new Mare {col('yellow')} --no-slot
add mesh cylinder --name Moon --vertices 16 --radius 2.6 --depth 0.2 --location 0 0 0 --rotation 90 0 0
apply --rotation
material assign Moon
mode edit
select face where "normal.y < -0.9"
poke
select face where "normal.y < -0.9"
subdivide --cuts 3
select face where "normal.y < -0.9 && (((pos.x - 0.8)*(pos.x - 0.8) + (pos.z - 0.6)*(pos.z - 0.6) < 0.5) || ((pos.x + 0.9)*(pos.x + 0.9) + (pos.z + 0.7)*(pos.z + 0.7) < 0.35) || ((pos.x - 0.3)*(pos.x - 0.3) + (pos.z + 1.3)*(pos.z + 1.3) < 0.2))"
material assign Mare
select face where "normal.y > 0.5"
delete only-faces
mode object
shade flat
export moon.glb
"""

# ---------------------------------------------------------------- clouds (a sea of clouds round the peak)
rnd = random.Random(5)
cl = []
n = 0
for ring_r, cnt in ((8.8, 12), (12.0, 14)):
    for k in range(cnt):
        a = 2 * math.pi * k / cnt + rnd.uniform(-0.1, 0.1)
        x = ring_r * math.cos(a) * 1.15; y = ring_r * math.sin(a) * 0.55 + 3.0
        r = rnd.uniform(1.4, 2.4)
        cl.append(f"add mesh ico-sphere --name C{n} --subdivisions 1 --radius {r:.2f} --location {x:.2f} {y:.2f} {rnd.uniform(-3.4, -2.6):.2f}")
        cl.append(f"scale 1.6 1.2 0.6\napply --scale")
        n += 1
files["clouds"] = f"""# Sea of clouds: flattened icosphere puffs in two rings round the mountain, below the terrace
# (their undersides and the faces turned away from the camera deleted).
# Built in place. Generated by make_env.py. Up Z, front -Y.
new
material new Cloud {col('steel')} --no-slot
""" + "\n".join(cl) + f"""
select {' '.join(f'C{i}' for i in range(n))}
active C0
join
rename C0 Clouds
material assign Cloud
mode edit
select face where "normal.z < -0.3 || normal.y > 0.5"
delete only-faces
mode object
shade flat
export clouds.glb
"""

# ---------------------------------------------------------------- stars
rnd = random.Random(9)
st = []
for i in range(46):
    x = rnd.uniform(-12, 12); z = rnd.uniform(3.2, 8.5)
    st.append(f"add mesh cube --name S{i} --size {rnd.choice([0.12, 0.12, 0.18]):.2f} --location {x:.2f} 15.5 {z:.2f}")
files["stars"] = f"""# Stars: tiny cubes on a plane behind the peaks (hedra y 15.5 = world z -15.5), high in the sky.
# Generated by make_env.py.
new
material new Star {col('white')} --no-slot
""" + "\n".join(st) + f"""
select {' '.join(f'S{i}' for i in range(46))}
active S0
join
rename S0 Stars
material assign Star
shade flat
export stars.glb
"""

# ---------------------------------------------------------------- ripple (a ring wave, largest size)
files["ripple"] = f"""# Ripple: a ring wave facing the camera, at its LARGEST size (radius 1.6 m): the game scales it up
# from small (bone scale moves splats apart but does not grow them). Origin at its centre.
new
material new Wave {col('white')} --no-slot
add mesh torus --name Ripple --major-segments 20 --minor-segments 4 --major-radius 1.6 --minor-radius 0.07 --location 0 0 0 --rotation 90 0 0
apply --rotation
material assign Wave
shade flat
export ripple.glb
"""

# ---------------------------------------------------------------- note spark
files["note"] = f"""# Note spark: a small octahedron (a diamond) that rises from a ringing bell. Origin at its centre.
new
material new Spark {col('yellow')} --no-slot
add mesh ico-sphere --name Note --subdivisions 1 --radius 0.18 --location 0 0 0
material assign Spark
shade flat
export note.glb
"""

for name, txt in files.items():
    with open(f"{name}.txt", "w") as f:
        f.write(txt)
print("wrote", ", ".join(f"{n}.txt" for n in files))
